<template>
    <div class="layout-px-spacing">

        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item">
                                <a href="javascript:;">Masters</a>
                            </li>
                            <li class="breadcrumb-item active">
                                <span>Services</span>
                            </li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        <div class="d-flex">
           <h4 class="mb-4">SITE MATERIAL ESTIMATIONS</h4>
           <div class="ms-auto">
            <button class="btn btn-success btn-sm" @click="printEstimate()" :disabled="!cbm || !selectedClass">
                <i class="bi bi-printer fs-5"></i>
            </button>
           </div>
        </div>


        <div class="row">

            <div class="col-md-4">
                <div class="card">
                    <div class="card-header">
                        <h5>Estimator</h5>
                    </div>

                    <div class="card-body">

                        <div class="mb-3">
                            <label class="form-label">Concrete Class</label>

                            <select
                                class="form-select"
                                v-model="selectedClass"
                            >
                                <option value="">Select Class</option>
                                <option
                                    v-for="(rate, key) in materialRates"
                                    :key="key"
                                    :value="key"
                                >
                                    Class {{ key }}
                                </option>
                            </select>
                        </div>

                        <div class="mb-3">
                            <label class="form-label">Quantity (CBM)</label>

                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                class="form-control"
                                v-model.number="cbm"
                                placeholder="Enter CBM"
                            >
                        </div>

                        <div class="mb-3">
                            <label class="form-label">
                                Wastage Factor (%)
                            </label>

                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                class="form-control"
                                v-model.number="wastage"
                                placeholder="Enter wastage %"
                            >
                        </div>

                    </div>
                </div>
            </div>

            <div
                class="col-md-8"
                v-if="selectedClass && cbm > 0"
            >
                <div class="card">
                    <div class="card-header">
                        <h5>Material Requirements</h5>
                    </div>

                    <div class="card-body">

<h6 class="mt-4">Material Requirement</h6>

<table class="table table-bordered">

    <thead class="table-light">
        <tr>
            <th>Material</th>
            <!-- <th>Rate per CBM</th> -->
            <th>Required Weight (KG)</th>
            <th>Required Quantity</th>
        </tr>
    </thead>

    <tbody>

        <tr>
            <td>Cement</td>

            <!-- <td>
                {{ materialRates[selectedClass].cementBagsPerM3 }} Bags/CBM
            </td> -->


            <td  class="text-end">
                {{ formatNumber(result.cementKg) }} KG
            </td>

            <td  class="text-end">
                {{ formatNumber(result.cementBags) }} Bags
            </td>


        </tr>

        <tr>
            <td>Sand</td>

            <!-- <td>
                {{ materialRates[selectedClass].sandM3PerM3 }} CBM/CBM
            </td> -->

            <td  class="text-end">
                {{ formatNumber(result.sandKg) }} KG
            </td>

            <td  class="text-end">
                {{ Number(result.sandVolume).toFixed(3) }} CBM
            </td>

        </tr>

        <tr>
            <td>Aggregate</td>

            <!-- <td>
                {{ materialRates[selectedClass].aggregateM3PerM3 }} CBM/CBM
            </td> -->


            <td  class="text-end">
                {{ formatNumber(result.aggregateKg) }} KG
            </td>

            <td  class="text-end">
                {{ Number(result.aggregateVolume).toFixed(3) }} CBM
            </td>

        </tr>

        <tr class="table-warning text-start">

            <th colspan="1"  class="text-start">
                Total Materials
            </th>

                        <th  class="text-end">
                {{ formatNumber(result.totalKg) }} KG
            </th>

            <th>
                -
            </th>



        </tr>

        <tr class="table-success ">

            <th colspan="1" class="text-start">
                Final Concrete Volume
            </th>


            <th>
                -
            </th>

           <th colspan="1" class="text-end">
                {{ cbm.toFixed(3) }} CBM
            </th>
        </tr>

    </tbody>

</table>
                    </div>
                </div>
            </div>

        </div>

    </div>
</template>

<script setup>
import { ref, computed, inject } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';

useMeta({ title: 'Material Estimates' });
const formatNumber = inject('formatNumber')
const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
});

const cbm = ref(null);
const selectedClass = ref('');
const wastage = ref('');

// Exact rates per 1 CBM of concrete, taken directly from the
// "SCHEDULE OF MATERIAL" table in Material_Formula.xls (sheet: CALC, rows 6-10).
// These figures already include the site's standard dry-volume/conversion
// allowance, so no separate shrinkage multiplier is applied on top.
const materialRates = {
    30: { cementBagsPerM3: 10,   sandM3PerM3: 0.5,   aggregateM3PerM3: 1.0  },
    25: { cementBagsPerM3: 7.6,  sandM3PerM3: 0.385, aggregateM3PerM3: 0.82 },
    20: { cementBagsPerM3: 6.08, sandM3PerM3: 0.42,  aggregateM3PerM3: 0.84 },
    15: { cementBagsPerM3: 4.3,  sandM3PerM3: 0.44,  aggregateM3PerM3: 0.88 },
    10: { cementBagsPerM3: 3.36, sandM3PerM3: 0.45,  aggregateM3PerM3: 0.95 }
};

// Material densities (kg/CBM) - used only to express sand/aggregate/cement
// quantities as weight for reference; they do not affect the CBM/bag figures.
const density = {
    cement: 1440,
    sand: 1600,
    aggregate: 1500
};


const result = computed(() => {

    if (!selectedClass.value || !cbm.value) {
        return {};
    }

    const rate = materialRates[selectedClass.value];

    const adjustmentFactor = 1 + (wastage.value / 100 || 0);

    const adjustedVolume = cbm.value * adjustmentFactor;


    const cementBags =
        adjustedVolume * rate.cementBagsPerM3;

    const sandVolume =
        adjustedVolume * rate.sandM3PerM3;

    const aggregateVolume =
        adjustedVolume * rate.aggregateM3PerM3;


    const cementKg =
        cementBags * 50; // standard 50kg cement bag

    const sandKg =
        sandVolume * density.sand;

    const aggregateKg =
        aggregateVolume * density.aggregate;


    const totalKg =
        cementKg + sandKg + aggregateKg;


    return {

        adjustedVolume: adjustedVolume.toFixed(3),

        cementBags: cementBags.toFixed(2),
        cementKg: cementKg.toFixed(2),

        sandVolume: sandVolume.toFixed(3),
        sandKg: sandKg.toFixed(2),

        aggregateVolume: aggregateVolume.toFixed(3),
        aggregateKg: aggregateKg.toFixed(2),

        totalKg: totalKg.toFixed(2)

    };

});

const triggerPrint = (content) => {

    const printWindow = window.open('', '_blank');

    printWindow.document.write(content);

    printWindow.document.close();

    printWindow.focus();

    printWindow.print();

    printWindow.close();

};

const printEstimate = () => {

    const rate = materialRates[selectedClass.value];

    const materialRows = [
        {
            name: 'Cement',
            rate: rate.cementBagsPerM3 + ' Bags/CBM',
            quantity: formatNumber(result.value.cementBags) + ' Bags',
            weight: result.value.cementKg
        },
        {
            name: 'Sand',
            rate: rate.sandM3PerM3 + ' CBM/CBM',
            quantity: Number(result.value.sandVolume).toFixed(3) + ' CBM',
            weight: result.value.sandKg
        },
        {
            name: 'Aggregate',
            rate: rate.aggregateM3PerM3 + ' CBM/CBM',
            quantity: Number(result.value.aggregateVolume).toFixed(3) + ' CBM',
            weight: result.value.aggregateKg
        }
    ];


    const rows = materialRows.map((item, index) => `
        <tr>
            <td>${index + 1}</td>
            <td>${item.name}</td>
            <td class="text-right">${formatNumber(item.weight)} KG</td>
            <td class="text-right">${item.quantity}</td>
        </tr>
    `).join('');


    const user = JSON.parse(localStorage.getItem('user'));


    const printContent = `
<!DOCTYPE html>
<html>

