    border:1px solid #000;
    padding:6px;
}

th {
    background:#f5f5f5;
}

.text-right {
    text-align:right;
}

hr {
    border:0;
    border-top:1px solid #000;
}

@media print {
    body {
        margin:10mm;
    }
}

</style>

</head>


<body>


<div class="company-title">

<i>

<h1>COPEX CONTRACTORS CO.LTD</h1>

<div>
<b>Address:</b> Msamvu, P.O.BOX 678, Morogoro
</div>

<div>
<b>Tel:</b> 0713 000 777, 0657 111 555
</div>

