</div>

<div>
<b>TIN:</b> 135-489-247
&nbsp;&nbsp;
<b>VRN:</b> 40-032826C
</div>

</i>

</div>


<hr style="margin-top:20px">


<div class="title">
SITE MATERIAL ESTIMATE REPORT
</div>


<hr>


<br>


<table>

<tr>
<th width="30%">
Concrete Class
</th>

<td>
Class ${selectedClass.value}
</td>
</tr>


<tr>
<th>
Concrete Volume
</th>

<td>
${Number(cbm.value).toFixed(3)} CBM
</td>
</tr>


<tr>
<th>
Wastage Factor
</th>

<td>
${wastage.value || 0} %
</td>
</tr>


</table>



<h3>
Material Requirement
</h3>



<table>

<thead>

<tr>

<th>No.</th>

<th>Material</th>


<th>Required Weight (KG)</th>


<th>Required Quantity</th>


</tr>

</thead>


<tbody>

${rows}


<tr>

<th colspan="2">
TOTAL WEIGHT
</th>


<th class="text-right">
${formatNumber(result.value.totalKg)} KG
</th>

<th>
    -
</th>


</tr>



<tr>

<th colspan="2">
FINAL CONCRETE VOLUME
</th>

<th>
    -
</th>

<th class="text-right">
${Number(cbm.value).toFixed(3)} CBM
</th>



</tr>


</tbody>

</table>



<div style="margin-top:20px;font-size:10px">

<p>
<strong>Generated At:</strong>
${new Date().toLocaleString()}
</p>


<p>
